def log1pexp(x):
    return jnp.log(1.0 + jnp.exp(x))

@jax.custom_jvp
def log1pexp_cjvp(x):
    return jnp.log(1.0 + jnp.exp(x))

@log1pexp_cjvp.defjvp
def _(primals, tangents):
    x, = primals; t, = tangents
    return log1pexp_cjvp(x), t * jax.nn.sigmoid(x)

def log1pexp_stable(x):              # no custom rule: a formula that never overflows
    return jnp.maximum(x, 0.0) + jnp.log1p(jnp.exp(-jnp.abs(x)))

