def norm(x):
    return jnp.sqrt(jnp.sum(x ** 2))       # d/ds sqrt(s) = 0.5 / sqrt(s): 0.5 / 0 = inf, and inf * 0 = nan

@jax.custom_jvp
def norm_safe(x):
    return jnp.sqrt(jnp.sum(x ** 2))

@norm_safe.defjvp
def _(primals, tangents):
    x, = primals; t, = tangents
    n = norm_safe(x)
    safe_n = jnp.where(n == 0.0, 1.0, n)
    return n, jnp.where(n == 0.0, 0.0, jnp.sum(x * t) / safe_n)

