def f(x):
    return jnp.where(x > 0, jnp.sqrt(x), 0.0)          # value right everywhere; gradient nan for x <= 0

def f_fixed(x):
    safe = jnp.where(x > 0, x, 1.0)                     # the untaken branch never sees a bad input
    return jnp.where(x > 0, jnp.sqrt(safe), 0.0)

